def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    strong_prev = []
    urgent_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid >= DAILY_SALARY * 0.8:
                    strong_prev.append(bid)

    if not alive_opponents:
        return max(0, min(budget, DAILY_SALARY * 0.25))

    max_prev_bid = max(prev_bids) if prev_bids else 0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    scarcity_ratio = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity_ratio = max(0.0, min(1.0, scarcity_ratio))

    my_urgent = hp <= 3 or no_water_days >= 2
    my_moderate = hp <= 5 or no_water_days >= 1

    if my_urgent:
        target = max(DAILY_SALARY * 0.95, max_prev_bid + 2.0)
        if supply >= 22:
            target *= 0.92
        return max(0, min(budget, target))

    if supply >= 23 and hp >= 7 and no_water_days == 0:
        return max(0, min(budget, DAILY_SALARY * 0.22))

    if supply <= 17:
        base = DAILY_SALARY * (0.62 + 0.18 * scarcity_ratio)
        if strong_prev:
            base = max(base, max_prev_bid + 1.5)
        if urgent_opp_count >= 2:
            base += 3.0
        if my_moderate:
            base += 6.0
        return max(0, min(budget, base))

    if max_prev_bid >= DAILY_SALARY * 1.4:
        if hp >= 7 and no_water_days == 0:
            return max(0, min(budget, DAILY_SALARY * 0.28))
        return max(0, min(budget, DAILY_SALARY * 0.72))

    if max_prev_bid >= DAILY_SALARY * 0.9:
        target = DAILY_SALARY * 0.52
        if my_moderate:
            target = DAILY_SALARY * 0.68
        if supply <= 19:
            target = max(target, max_prev_bid + 1.0)
        return max(0, min(budget, target))

    target = DAILY_SALARY * 0.42 + scarcity_ratio * 10.0
    if avg_prev_bid > 0:
        target = max(target, min(avg_prev_bid + 1.0, DAILY_SALARY * 0.7))
    if my_moderate:
        target += 5.0

    return max(0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    alive_opponents = [o for o_id, o in opponents_status.items() if o['alive']]

    # Base bid strategy: Default to a moderate bid
    bid = DAILY_SALARY * 0.7

    # Phase 1: Critical Survival (Low HP)
    # If HP is very low, bid aggressively to survive
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    # Phase 2: No active opponents
    # If no opponents are alive, bid minimally to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Phase 3: Analyze specific opponents (Cindy)
    cindy_prev_bid = 0.0
    cindy_is_alive = False
    for opp_id, opp in opponents_status.items():
        if opp_id == "Cindy" and opp['alive']:
            cindy_is_alive = True
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                cindy_prev_bid = float(prev['bid'])
            break

    if cindy_is_alive:
        if cindy_prev_bid > DAILY_SALARY:
            # Cindy bids very high, need to compete aggressively
            bid = max(bid, cindy_prev_bid + 5)
            # Cap the extremely high bid if my HP is not critically low
            if my_status['hp'] > 4:
                bid = min(bid, DAILY_SALARY * 1.15) # Don't overspend too much if not desperate
        elif cindy_prev_bid > 0:
            # Cindy bids moderately, bid slightly above
            bid = max(bid, cindy_prev_bid + 2)

    # Phase 4: Adjust based on competition and supply
    available_water_units = int(day_context['supply'] // WATER_REQ)

    num_players_needing_water = 1 # For myself
    for opp in alive_opponents:
        if opp['water_requirement'] > 0:
            num_players_needing_water += 1

    if num_players_needing_water > available_water_units:
        # High competition: supply is scarce relative to demand
        # Increase bid, especially if Cindy is a factor
        if cindy_is_alive and cindy_prev_bid > 0:
            bid = max(bid, cindy_prev_bid + 10)
        else:
            bid = max(bid, DAILY_SALARY * 0.9)
    elif num_players_needing_water <= available_water_units:
        # Low competition: supply is abundant
        # Decrease bid to save budget, but only if my HP is good
        if my_status['hp'] > 5:
            bid = min(bid, DAILY_SALARY * 0.6)

    # Phase 5: Late game aggression
    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['budget'] > DAILY_SALARY * 2 and my_status['hp'] > 0:
        # If it's near the end and I have a good budget, secure the win
        bid = max(bid, DAILY_SALARY * 1.1)

    # Final Bid Constraints
    final_bid = min(my_status['budget'], bid)
    final_bid = max(1.0, final_bid) # Ensure bid is at least 1.0

    return final_bid

