    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Collect yesterday's bids from opponent traces
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid
    base_bid = DAILY_SALARY * 0.55

    # Urgency based on HP
    hp = my_status['hp']
    if hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif hp <= 4:
        base_bid = DAILY_SALARY * 0.7

    # Adjust based on yesterday's highest bid
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If competitors were aggressive, we may need to increase
        if max_prev > DAILY_SALARY * 0.85:
            if hp > 4:
                base_bid = min(base_bid, DAILY_SALARY * 0.5)
            else:
                base_bid = max(base_bid, max_prev + 2.0)
        else:
            # Slightly beat the highest previous bid if we need water
            if hp <= 4:
                base_bid = max(base_bid, max_prev + 1.5)
            else:
                base_bid = min(base_bid, max_prev - 5.0)

    # Clamp to budget
    final_bid = min(my_status['budget'], base_bid)
    # Ensure non-negative
    final_bid = max(0.0, final_bid)
    return int(final_bid) if final_bid == int(final_bid) else final_bid
